	"time"

	"example.com/go-mini/internal/snapshot"
)

func TestParseRetention_Success(t *testing.T) {
	tests := []struct {
		name string
		raw  string
		days int
	}{
		{name: "bare number", raw: "30", days: 30},
		{name: "d suffix", raw: "30d", days: 30},
		{name: "minimum", raw: "1d", days: 1},
		{name: "maximum", raw: "365d", days: 365},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			r, err := snapshot.ParseRetention(policy(tc.raw))
			if err != nil {
				t.Fatalf("ParseRetention(%q): %v", tc.raw, err)
			}

			now := time.Date(2024, time.March, 1, 0, 0, 0, 0, time.UTC)
			atBoundary := now.Add(-time.Duration(tc.days) * 24 * time.Hour)
			pastBoundary := now.Add(-time.Duration(tc.days+1) * 24 * time.Hour)

			if r.Expired(atBoundary, now) {
				t.Errorf("snapshot exactly %d days old should not be expired yet", tc.days)
			}
			if !r.Expired(pastBoundary, now) {
				t.Errorf("snapshot older than %d days should be expired", tc.days)
			}
		})
	}
}

func TestParseRetention_Error(t *testing.T) {
	tests := []struct {
		name string
		raw  map[string]string
	}{
		{name: "missing key", raw: map[string]string{}},
		{name: "empty value", raw: policy("")},
		{name: "not a number", raw: policy("soon")},
		{name: "zero days", raw: policy("0d")},
		{name: "negative days", raw: policy("-5d")},
		{name: "too many days", raw: policy("366d")},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := snapshot.ParseRetention(tc.raw); err == nil {
				t.Fatalf("ParseRetention(%v) = nil, want error", tc.raw)
			}
		})
	}
}

