package snapshot

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// Retention is how long a snapshot is kept before Prune treats it as expired.
type Retention struct {
	days int
}

// ParseRetention reads the "retention" key out of raw — an integer day count,
// optionally suffixed "d" — and validates it falls within 1-365 days.
func ParseRetention(raw map[string]string) (Retention, error) {
	v, ok := raw["retention"]
	if !ok || v == "" {
		return Retention{}, errors.New("retention missing")
	}
	days, err := strconv.Atoi(strings.TrimSuffix(v, "d"))
	if err != nil || days <= 0 || days > 365 {
		return Retention{}, fmt.Errorf("retention %q out of range 1-365 days", v)
	}
	return Retention{days: days}, nil
}

// Expired reports whether a snapshot created at createdAt has outlived this
// retention as of now.
func (r Retention) Expired(createdAt, now time.Time) bool {
	age := int(now.Sub(createdAt).Hours() / 24)
	return age > r.days
}

